import { useCallback, useState } from 'react';
import { Button, Divider, Drawer, Stack } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type SideNavProps = {
  onNavigate: (key: NavKey) => void;
};

const NAV_ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function SideNav({ onNavigate }: SideNavProps) {
  const [open, setOpen] = useState(false);

  const close = useCallback(() => setOpen(false), []);

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <>
      <Button variant="secondary" onClick={() => setOpen(true)}>
        Меню
      </Button>

      <Drawer open={open} onClose={close} placement="left" title="Навигация">
        <Stack as="nav" direction="column" gap="var(--jx-space-1)">
          {NAV_ITEMS.map((item) => (
            <Button
              key={item.key}
              variant="ghost"
              align="start"
              fullWidth
              onClick={() => select(item.key)}
            >
              {item.label}
            </Button>
          ))}

          <Divider spacing="var(--jx-space-2)" />

          <Button
            variant="ghost"
            tone="danger"
            align="start"
            fullWidth
            onClick={() => select('logout')}
          >
            Выйти
          </Button>
        </Stack>
      </Drawer>
    </>
  );
}

